question.answer:
def naive_add(a: int, b: int) -> int:
    return a + b


def lie_report() -> str:
    result = naive_add("1", "2")
    declared: str = naive_add.__annotations__["return"].__name__
    actual: str = type(result).__name__
    return f"declared {declared}, returned {actual} {result!r}"


def checked_add(a: int, b: int) -> int:
    if isinstance(a, bool) or not isinstance(a, int):
        raise TypeError(f"checked_add needs an int for a, got {type(a).__name__}")
    if isinstance(b, bool) or not isinstance(b, int):
        raise TypeError(f"checked_add needs an int for b, got {type(b).__name__}")
    return a + b


def read_pressure(raw: str) -> float:
    if not isinstance(raw, str):
        raise TypeError(f"read_pressure needs a str, got {type(raw).__name__}")
    value: float = float(raw)
    if value < 0.0 or value > 250.0:
        raise ValueError(f"pressure {value} is outside 0.0 to 250.0")
    return value

